 font-size: 24px; font-weight: 600; line-height: 1.25; }.ps-showcase-copy p { color: rgb(77, 77, 77); font-size: 18px; font-weight: 500; line-height: 1.6; }.ps-dots { display: flex; align-items: center; gap: 8px; padding-top: 16px; }.ps-dots span { display: flex; align-items: center; justify-content: center; width: 24px; height: 24px; flex-shrink: 0; }.ps-dots i { width: 10px; height: 10px; border-radius: 999px; background: rgb(228, 228, 231); }.ps-dots .on i { background: rgb(24, 24, 27); }.ps-launch { padding-top: 8px; }.ps-launch a { display: inline-flex; align-items: center; gap: 6px; color: rgb(24, 24, 27); font-size: 15px; font-weight: 500; line-height: 28px; }.ps-launch a span { transition: transform 0.2s; }.ps-launch a:hover span { transform: translateX(3px); }.ps-show-media { position: relative; min-width: 0px; padding: 16px; border-radius: 16px; background: rgb(10, 24, 13); overflow: clip; }.ps-plate-show { aspect-ratio: 960 / 521; }.ps-plate-show #stmMobileFit { border-radius: 0px; box-shadow: none; height: 100% !important; }.ps-plate-show #mvdRoot { height: 521px; }.ps-replay-show { right: 28px; bottom: 28px; border-color: rgb(228, 228, 231); background: rgba(255, 255, 255, 0.9); color: rgb(100, 100, 100); box-shadow: rgba(0, 0, 0, 0.06) 0px 1px 2px; }.ps-replay-show:hover { background: rgb(255, 255, 255); color: rgb(23, 23, 23); }.ps-cta { position: relative; display: flex; align-items: center; justify-content: space-between; gap: 40px; min-height: 146px; padding: 40px 48px; border-radius: 16px; background: rgb(10, 24, 13); overflow: clip; }.ps-cta > :not(.ps-warp) { position: relative; z-index: 1; }.ps-cta-copy { display: flex; flex-direction: column; gap: 8px; max-width: 640px; }.ps-cta h2 { color: rgb(255, 255, 255); font-family: "Inter Tight", system-ui, sans-serif; font-size: 28px; font-weight: 600; line-height: 1.2; }.ps-cta p { color: rgb(255, 255, 255); font-size: 16px; font-weight: 500; line-height: 1.5; }.ps-cta-btn { flex-shrink: 0; padding: 