e: 14px; }.ps-footer { padding: 0px 16px 16px; }.ps-footer-inner { position: relative; min-height: 501px; border-radius: 16px; background: url("/replays/assets/5b8124eca09b.jpg") 50% 40% / cover no-repeat rgb(10, 24, 13); overflow: hidden; font-family: "Inter Tight", system-ui, sans-serif; color: rgb(255, 255, 255); }.ps-footer-bg { position: absolute; inset: 0px; border-radius: 16px; }.ps-footer-bg canvas { display: block; }.ps-footer-col { position: relative; z-index: 1; width: min(1160px, 100% - 32px); margin-inline: auto; padding: 109.5px 0px 101.5px; }.ps-footer-mark { display: block; width: 200px; height: 15px; }.ps-footer-cols { display: flex; align-items: flex-start; justify-content: space-between; gap: 48px; margin-top: 48px; }.ps-footer-about { display: flex; flex-direction: column; gap: 16px; width: 280px; flex-shrink: 0; }.ps-footer-k { font-size: 13px; font-weight: 600; line-height: 16px; letter-spacing: 0.08em; text-transform: uppercase; opacity: 0.7; }.ps-footer-k-sm { font-size: 12px; }.ps-footer-lead { font-size: 18px; font-weight: 600; line-height: 1.3; }.ps-footer-sub { font-size: 14px; line-height: 1.5; opacity: 0.85; }.ps-footer-links { flex: 1 1 0%; display: flex; justify-content: flex-end; gap: 48px; }.ps-footer-group { display: flex; flex-direction: column; gap: 10px; font-size: 14px; line-height: 18px; }.ps-footer-group a:hover { text-decoration: underline; text-underline-offset: 3px; }.ps-footer-addr { line-height: 1.45; }.ps-footer-base { display: flex; align-items: center; justify-content: space-between; margin-top: 48px; padding-top: 24px; border-top: 1px solid rgba(255, 255, 255, 0.2); font-size: 13px; line-height: 16px; opacity: 0.75; }.ps-back { position: fixed; z-index: 60; left: 16px; bottom: 16px; padding: 6px 12px; border: 1px solid rgb(228, 228, 231); border-radius: 999px; background: rgba(255, 255, 255, 0.9); color: rgb(115, 115, 115); font-size: 12px; font-weight: 500; line-height: 16px; backdrop-filter: blur(6px); box-shadow: 